const b = $json.body ?? $json;
const allowed = ['contact_id', 'template_key', 'explicit_instruction', 'explicit_send'];
if (Object.keys(b).some(k => !allowed.includes(k))) throw Error('Only a contact ID and fixed template are accepted');
const id = Number(b.contact_id);
const keys = ['questionnaire_invitation', 'questionnaire_reminder', 'property_details', 'viewing_next_steps', 'viewing_request_received'];
const command = String(b.explicit_instruction ?? '');
if (!Number.isInteger(id) || id < 1) throw Error('contact_id must be positive');
if (!keys.includes(b.template_key)) throw Error('Unsupported template_key');
if (b.explicit_send !== true || !/\b(send|email|e-mail|dispatch)\b/i.test(command) ||
    /\b(do not|don't|never|not to)\s+(?:\w+\s+){0,2}(send|email|e-mail|dispatch)\b/i.test(command)) {
  throw Error('An explicit current user send instruction is required');
}
return [{json: {contact_id: id, template_key: b.template_key}}];

const a = $('Validate request').first().json;
const d = $json;
if (d.error || Number(d.id) !== a.contact_id) throw Error('Backend contact identity could not be verified');
const email = String(d.email ?? '');
if (!/^[^\s,;<>@]+@[^\s,;<>@]+\.[^\s,;<>@]+$/.test(email) || /[\r\n]/.test(email)) throw Error('Contact has no single valid email address');
const clean = v => String(v ?? '').replace(/[\r\n<>]/g, ' ').trim();
const name = [clean(d.first_name), clean(d.last_name)].filter(Boolean).join(' ') || 'there';
const property = clean(d.property_address);
function activeLink(purpose) {
  const link = d.links?.[purpose];
  const meta = d.tokens?.[purpose];
  if (typeof link !== 'string' || !meta || meta.consumed_at || !(Date.parse(meta.expires_at) > Date.now())) return null;
  // Use only the backend-issued link, never generate or reissue a token here.
  const valid = purpose === 'questionnaire' ?
    /^https:\/\/thamesvalley-estate-agents\.vercel\.app\/questionnaire\/[A-Za-z0-9_.-]+$/ :
    /^https:\/\/thamesvalley-estate-agents-booking\.vercel\.app\/booking\/[A-Za-z0-9_.-]+$/;
  return valid.test(link) ? link : null;
}
let subject, paragraphs;
if (a.template_key === 'questionnaire_reminder') {
  const link = activeLink('questionnaire');
  if (!['enquiried', 'Questionnaire_sent'].includes(d.status) || !link) {
    throw Error('No active backend questionnaire link; explicitly request questionnaire_invitation to reissue it');
  }
  subject = 'Reminder: complete your rental questionnaire';
  paragraphs = [`Dear ${name},`, 'A friendly reminder to complete your rental questionnaire so we can progress your enquiry.',
    'Please use your secure questionnaire link:', link, 'If you have any questions, reply to this email and our lettings team will help.'];
} else if (a.template_key === 'property_details') {
  if (!d.property_id || !property) throw Error('No verified property is linked to this contact');
  const details = [property];
  if (Number.isFinite(d.property_rent)) details.push(`Monthly rent: GBP ${d.property_rent}`);
  if (Number.isFinite(d.property_bedrooms)) details.push(`Bedrooms: ${d.property_bedrooms}`);
  subject = 'Your property enquiry - property details';
  paragraphs = [`Dear ${name},`, 'The details of the property linked to your enquiry are:', details.join('\n'),
    'Please reply if you would like more information or help with the next steps.'];
} else if (a.template_key === 'viewing_next_steps') {
  const link = activeLink('booking');
  if (!['questionnaire_completed', 'viewing_requested'].includes(d.status) || !link) throw Error('No active backend booking link for this contact');
  subject = 'Next steps for your viewing';
  paragraphs = [`Dear ${name},`, `Thank you for your interest in ${property || 'the property'}.`,
    'Please use your secure link to request a suitable viewing time:', link,
    'A viewing request is not a confirmed appointment. Our team will contact you to confirm arrangements.'];
} else if (a.template_key === 'viewing_request_received') {
  if (d.status !== 'viewing_requested') throw Error('The backend does not show a pending viewing request');
  subject = 'We received your viewing request';
  paragraphs = [`Dear ${name},`, `We received your viewing request for ${property || 'the property'}.`,
    'This is not a confirmed booking. Our team will contact you to confirm an available time.'];
} else throw Error('Unsupported plain-text template');
paragraphs.push('Kind regards,\nThames Valley Estates');
return [{json: {toEmail: email, subject, text: paragraphs.join('\n\n'), contact_id: a.contact_id}}];
